#include <bits/stdc++.h>
using namespace std;

int main() {

	int N;
	cin>>N;

	vector<bool> vol(N+2,false);
	vector<int> a(N);

	int sold = 0;
	for(int i=0;i<N;i++){
		cin>>a[i];
		if(a[i]>=vol.size())sold++;
		else if(vol[a[i]])sold++;
		else vol[a[i]] = true;
	}

	int L = 1;
	int R = N+1;
	while(true){
		while(vol[L])L++;
		while(R!=0&&!vol[R])R--;
		if(sold>=2){
			sold-=2;
			vol[L] = true;
		}
		else{
			if(L>=R)break;
			vol[R] = false;
			sold++;
		}
	}

	cout<<L-1<<endl;

	return 0;
}

#include<iostream>
#include<vector>
using namespace std;
int main() {
  int N;
  cin >> N;
  vector<bool> set(N + 2);
  for (int i = 0;i < N;++ i) {
    int a;
    cin >> a;
    set[min(N + 1, a)] = true;
  }
  for (int read = 1;N >= 0;++ read) {
    N -= set[read] ? 1 : 2; // その巻を読むために使う本の冊数
    if (N < 0) cout << read - 1 << endl; // 本が無くなったら、無くなる直前の冊数を出力
  }
}

import java.util.Scanner;
import static java.lang.System.out;
public class Main {
  public static void main(String[] args) {
    try (Scanner sc = new Scanner(System.in)) {
      int N = sc.nextInt();
      boolean[] a = new boolean[N + 2];
      for (int i = 0;i < N;++ i) a[Math.min(N + 1, sc.nextInt())] = true;
      for (int read = 1;N >= 0;++ read) {
        N -= a[read] ? 1 : 2; // その巻を読むために使う本の冊数
        if (N < 0) out.println(read - 1); // 本が無くなったら、無くなる直前の冊数を出力
      }
    }
  }
}

